package com.tripsync.service;
import com.tripsync.entity.*;import com.tripsync.repository.*;import com.tripsync.dto.InvitationDtos.*;import org.springframework.stereotype.Service;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;
@Service public class InvitationService{private final TripService trips;private final GroupInvitationRepository invitations;private final GroupMemberRepository members;public InvitationService(TripService t,GroupInvitationRepository i,GroupMemberRepository m){trips=t;invitations=i;members=m;}
 public InvitationResponse create(UUID groupId,String user,String invitee){trips.requireMember(groupId,user);TripGroup g=trips.requireMember(groupId,user);if(!g.getOwnerId().equals(user))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only trip owner can invite members");String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");Instant expiry=Instant.now().plus(Duration.ofDays(7));GroupInvitation i=invitations.save(new GroupInvitation(groupId,token,invitee,expiry));return new InvitationResponse(i.getId(),token,"/join/"+token,expiry);}
 public void accept(String token,String user){GroupInvitation i=invitations.findByToken(token).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invitation not found"));if(!i.getStatus().equals("PENDING")||i.getExpiresAt().isBefore(Instant.now()))throw new ResponseStatusException(HttpStatus.GONE,"Invitation expired or already used");if(members.existsByGroupIdAndUserId(i.getGroupId(),user))throw new ResponseStatusException(HttpStatus.CONFLICT,"Already a member");members.save(new GroupMember(i.getGroupId(),user,"MEMBER"));i.accept();invitations.save(i);}}
